INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '填空', 2, '{"stem": "小海妈妈买了5盒铅笔，每盒8支，每支4元。列式“5×8×4”中，先算“5×8”，表示（ ）；再算“40×4”，表示（ ）。这一题还可以这样列式：（ ）。", "options": null}', '5盒铅笔一共有40支；40支铅笔一共要付160元；8×4×5', '先算 5×8=40（支），求出铅笔的总支数；再算 40×4=160（元），求出一共要付的钱数。也可以先算每盒要付 8×4=32（元），再算 5 盒共 32×5=160（元），列式为 8×4×5。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "学校啦啦操队参加比赛，需要变换队形。如果6人一排，可以排4排；如果8人一排，可以排多少排？", "options": null}', '3排', '先求总人数：6×4=24（人）；再求 8 人一排能排几排：24÷8=3（排）。综合算式：6×4÷8=3。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 2, '{"stem": "小华爸爸买了8元钱的萝卜，买土豆的钱数是萝卜的一半，买青菜的钱数比土豆多3元。小华爸爸买青菜花了多少元？", "options": null}', '7元', '先求土豆的钱：8÷2=4（元）；青菜比土豆多 3 元：4+3=7（元）。综合算式：8÷2+3=7。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "1份樱桃的价钱相当于3份枇杷的价钱，1份枇杷的价钱又相当于5份苹果的价钱。1份樱桃90元，1份苹果多少元？", "options": null}', '6元', '先求 1 份枇杷：90÷3=30（元）；再求 1 份苹果：30÷5=6（元）。综合算式：90÷3÷5=6。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.1"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1013, '数学', '三年级', '应用题', 3, '{"stem": "4个小朋友5分钟能做20个幸运星。照这样计算，7个小朋友10分钟能做多少个幸运星？", "options": null}', '70个', '先求 1 个小朋友 1 分钟做几个：20÷5÷4=1（个）；再求 7 个小朋友 10 分钟做几个：1×7×10=70（个）。也可：20÷4÷5=1，1×7×10=70。', 'paper', '["practice", "VG-G3-1-5", "ykl3sx", "1.1"]', NULL, 0);
